-- TABLE: risk_scores
CREATE TABLE __SCHEMA__.risk_scores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    identity_id bigint,
    credential_id uuid,
    overall_score integer NOT NULL,
    privilege_score integer,
    exposure_score integer,
    staleness_score integer,
    sprawl_score integer,
    ownership_score integer,
    risk_factors jsonb,
    scan_id text NOT NULL,
    calculated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_exposure CHECK (((exposure_score IS NULL) OR ((exposure_score >= 0) AND (exposure_score <= 100)))),
    CONSTRAINT chk_overall CHECK (((overall_score >= 0) AND (overall_score <= 100))),
    CONSTRAINT chk_ownership CHECK (((ownership_score IS NULL) OR ((ownership_score >= 0) AND (ownership_score <= 100)))),
    CONSTRAINT chk_priv CHECK (((privilege_score IS NULL) OR ((privilege_score >= 0) AND (privilege_score <= 100)))),
    CONSTRAINT chk_sprawl CHECK (((sprawl_score IS NULL) OR ((sprawl_score >= 0) AND (sprawl_score <= 100)))),
    CONSTRAINT chk_stale CHECK (((staleness_score IS NULL) OR ((staleness_score >= 0) AND (staleness_score <= 100))))
);

